 public static String label(String key,boolean russian){String source=AppearanceEditorPolicy.plain(key).replaceAll("([a-z0-9])([A-Z])","$1 $2").replaceAll("[_.]"," ");ArrayList<String> parts=new ArrayList<>();for(String word:source.split(" +")){if(word.isEmpty())continue;parts.add(russian?RU.getOrDefault(word.toLowerCase(Locale.ROOT),word):Character.toUpperCase(word.charAt(0))+word.substring(1));}return String.join(" · ",parts);}
